# Convert to JSON format for submission
bg = 4
visited = [[False]*len(test_input[0]) for _ in range(len(test_input))]
frames = []

def find_connected_region(start_r, start_c, color):
    region = []
    stack = [(start_r, start_c)]
    visited[start_r][start_c] = True

    while stack:
        r, c = stack.pop()
        region.append((r, c))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if (0 <= nr < len(test_input) and 0 <= nc < len(test_input[0]) 
                and not visited[nr][nc] and test_input[nr][nc] == color):
                visited[nr][nc] = True
                stack.append((nr, nc))

    min_r = min(r for r, c in region)
    max_r = max(r for r, c in region)
    min_c = min(c for r, c in region)
    max_c = max(c for r, c in region)

    return {'color': color, 'min_r': min_r, 'max_r': max_r, 
            'min_c': min_c, 'max_c': max_c}

for r in range(len(test_input)):
    for c in range(len(test_input[r])):
        if test_input[r][c] != bg and not visited[r][c]:
            frames.append(find_connected_region(r, c, test_input[r][c]))

output = [row[:] for row in test_input]

frame_bboxes = []
for fd in frames:
    ext_h = fd['max_r'] - fd['min_r'] + 1
    ext_w = fd['max_c'] - fd['min_c'] + 1
    int_h = ext_h - 2
    int_w = ext_w - 2

    fill_val = 2 if (int_h == 2 and int_w == 2) else 7
    frame_bboxes.append((fd['min_r'], fd['max_r'], fd['min_c'], fd['max_c'], fill_val))

for r0, r1, c0, c1, fill_val in frame_bboxes:
    for r in range(r0+1, r1):
        for c in range(c0+1, c1):
            output[r][c] = fill_val

import json
print(json.dumps(output))

